import java.util.*;

class Solution {
    public TreeNode lowestCommonAncestor(TreeNode root, TreeNode p, TreeNode q) {
        List<TreeNode> pathP = new ArrayList<>();
        List<TreeNode> pathQ = new ArrayList<>();
        findPath(root, p, pathP);
        findPath(root, q, pathQ);

        TreeNode lca = null;
        int n = Math.min(pathP.size(), pathQ.size());
        for (int i = 0; i < n; i++) {
            if (pathP.get(i) == pathQ.get(i)) lca = pathP.get(i);   // 比引用
            else break;
        }
        return lca;
    }

    private boolean findPath(TreeNode node, TreeNode target, List<TreeNode> path) {
        if (node == null) return false;
        path.add(node);
        if (node == target) return true;
        if (findPath(node.left, target, path)) return true;
        if (findPath(node.right, target, path)) return true;
        path.remove(path.size() - 1);   // 回溯
        return false;
    }
}

class Solution {
    public TreeNode lowestCommonAncestor(TreeNode root, TreeNode p, TreeNode q) {
        if (root == null || root == p || root == q) return root;

        TreeNode left = lowestCommonAncestor(root.left, p, q);
        TreeNode right = lowestCommonAncestor(root.right, p, q);

        if (left != null && right != null) return root;   // 分居两侧
        return left != null ? left : right;
    }
}

import java.util.*;

class Solution {
    public TreeNode lowestCommonAncestor(TreeNode root, TreeNode p, TreeNode q) {
        Map<TreeNode, TreeNode> parent = new HashMap<>();
        Deque<TreeNode> queue = new ArrayDeque<>();
        parent.put(root, null);
        queue.offer(root);

        // 建父指针，直到 p 和 q 都被记录
        while (!queue.isEmpty()) {
            TreeNode cur = queue.poll();
            if (cur.left != null) {
                parent.put(cur.left, cur);
                queue.offer(cur.left);
            }
            if (cur.right != null) {
                parent.put(cur.right, cur);
                queue.offer(cur.right);
            }
        }

        Set<TreeNode> ancestors = new HashSet<>();
        for (TreeNode node = p; node != null; node = parent.get(node)) {
            ancestors.add(node);
        }

        for (TreeNode node = q; node != null; node = parent.get(node)) {
            if (ancestors.contains(node)) return node;   // 第一个撞上的就是 LCA
        }
        return null;
    }
}
